//! Byte-exact parity of the FST engine's ITN against NeMo's own output.
//!
//! Fixtures in `tests/fixtures/itn/<lang>/` hold NeMo's `InverseNormalizer`
//! output (input_case=cased) on NeMo-text-processing's ITN test inputs (Apache-2.0,
//! pinned commit `1f1263579fe57ba7ed783cad3dddee710fcc5064`), regenerated by
//! `scripts/generate_nemo_fixtures.py`, so this runs in CI without a NeMo checkout.
//!
//! Requires the `fst-engine` feature: `cargo test --features fst-engine`.
#![cfg(feature = "fst-engine")]

mod common;

use std::fs;
use std::path::Path;
use text_processing_rs::fst;

/// Assert every `test_cases_*.txt` under `tests/fixtures/itn/<lang>/` inverse-normalizes
/// byte-for-byte, and that a meaningful number of cases actually ran.
fn assert_lang_parity(lang: &str, min_cases: usize) {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/itn")
        .join(lang);
    let mut total = 0;
    for entry in fs::read_dir(&dir).expect("fixtures dir") {
        let path = entry.unwrap().path();
        let name = path.file_name().unwrap().to_string_lossy().to_string();
        if !name.starts_with("test_cases_") {
            continue;
        }
        total += common::parse_test_file(&path).len();
        common::assert_test_file(&path, |input| {
            fst::inverse_normalize_lang(input, lang).expect("supported language")
        });
    }
    assert!(
        total >= min_cases,
        "{lang}: expected >= {min_cases} cases, saw only {total}"
    );
}

#[test]
fn en_itn_matches_nemo() {
    assert_lang_parity("en", 1200);
}

#[test]
fn de_itn_matches_nemo() {
    assert_lang_parity("de", 280);
}

#[test]
fn es_itn_matches_nemo() {
    assert_lang_parity("es", 370);
}

#[test]
fn fr_itn_matches_nemo() {
    assert_lang_parity("fr", 300);
}

#[test]
fn hi_itn_matches_nemo() {
    assert_lang_parity("hi", 340);
}

#[test]
fn ja_itn_matches_nemo() {
    assert_lang_parity("ja", 220);
}

#[test]
fn zh_itn_matches_nemo() {
    assert_lang_parity("zh", 380);
}
